// AgentServiceServer is the server API for AgentService service.
// All implementations must embed UnimplementedAgentServiceServer
// for forward compatibility.
type AgentServiceServer interface {
	RegisterHost(context.Context, *RegisterHostRequest) (*RegisterHostResponse, error)
	Heartbeat(context.Context, *HeartbeatRequest) (*HeartbeatResponse, error)
	GetHostStatus(context.Context, *GetHostStatusRequest) (*HostStatus, error)
	CreateVM(context.Context, *CreateVMRequest) (*CreateVMResponse, error)
	GetVMDetails(context.Context, *GetVMDetailsRequest) (*GetVMDetailsResponse, error)
	UpdateVM(context.Context, *UpdateVMRequest) (*UpdateVMResponse, error)
	DeleteVM(context.Context, *DeleteVMRequest) (*DeleteVMResponse, error)
	StartVM(context.Context, *StartVMRequest) (*StartVMResponse, error)
	StopVM(context.Context, *StopVMRequest) (*StopVMResponse, error)
	ForceStopVM(context.Context, *ForceStopVMRequest) (*ForceStopVMResponse, error)
	RebootVM(context.Context, *RebootVMRequest) (*RebootVMResponse, error)
	PauseVM(context.Context, *PauseVMRequest) (*PauseVMResponse, error)
	ResumeVM(context.Context, *ResumeVMRequest) (*ResumeVMResponse, error)
	InitiateMigration(context.Context, *InitiateMigrationRequest) (*InitiateMigrationResponse, error)
	PrepareForMigration(context.Context, *PrepareForMigrationRequest) (*PrepareForMigrationResponse, error)
	ConfirmMigration(context.Context, *ConfirmMigrationRequest) (*emptypb.Empty, error)
	AbortMigration(context.Context, *AbortMigrationRequest) (*emptypb.Empty, error)
	CreateSnapshot(context.Context, *CreateSnapshotRequest) (*CreateSnapshotResponse, error)
	RevertToSnapshot(context.Context, *RevertToSnapshotRequest) (*RevertToSnapshotResponse, error)
	DeleteSnapshot(context.Context, *DeleteSnapshotRequest) (*DeleteSnapshotResponse, error)
	GetTaskStatus(context.Context, *GetTaskStatusRequest) (*Task, error)
	CancelTask(context.Context, *CancelTaskRequest) (*CancelTaskResponse, error)
	ConfigureNetwork(context.Context, *ConfigureNetworkRequest) (*ConfigureNetworkResponse, error)
	ConfigureStorage(context.Context, *ConfigureStorageRequest) (*ConfigureStorageResponse, error)
	ConfigureTime(context.Context, *ConfigureTimeRequest) (*ConfigureTimeResponse, error)
	SetMaintenanceMode(context.Context, *SetMaintenanceModeRequest) (*SetMaintenanceModeResponse, error)
	UpdateHost(context.Context, *UpdateHostRequest) (*UpdateHostResponse, error)
	GetContentLibraryItems(context.Context, *GetContentLibraryItemsRequest) (*GetContentLibraryItemsResponse, error)
	UploadContentLibraryItem(grpc.ClientStreamingServer[UploadContentLibraryItemRequest, UploadContentLibraryItemResponse]) error
	ExportOVA(*ExportOVARequest, grpc.ServerStreamingServer[ExportOVAResponse]) error
	ImportOVA(grpc.ClientStreamingServer[ImportOVARequest, ImportOVAResponse]) error
	DeleteContentLibraryItem(context.Context, *DeleteContentLibraryItemRequest) (*DeleteContentLibraryItemResponse, error)
	GetDatastores(context.Context, *GetDatastoresRequest) (*GetDatastoresResponse, error)
	GetDatastore(context.Context, *GetDatastoreRequest) (*GetDatastoreResponse, error)
	CreateDatastore(context.Context, *CreateDatastoreRequest) (*CreateDatastoreResponse, error)
	DeleteDatastore(context.Context, *DeleteDatastoreRequest) (*DeleteDatastoreResponse, error)
	GetNetworks(context.Context, *GetNetworksRequest) (*GetNetworksResponse, error)
	GetNetwork(context.Context, *GetNetworkRequest) (*GetNetworkResponse, error)
	CreateNetwork(context.Context, *CreateNetworkRequest) (*CreateNetworkResponse, error)
	DeleteNetwork(context.Context, *DeleteNetworkRequest) (*DeleteNetworkResponse, error)
	AttachIso(context.Context, *AttachIsoRequest) (*AttachIsoResponse, error)
	DetachIso(context.Context, *DetachIsoRequest) (*DetachIsoResponse, error)
	CloneVmFromTemplate(context.Context, *CloneVmFromTemplateRequest) (*CloneVmFromTemplateResponse, error)
	GetVMGuestIPs(context.Context, *GetVMGuestIPsRequest) (*GetVMGuestIPsResponse, error)
	ChangeVMUserPassword(context.Context, *ChangeVMUserPasswordRequest) (*ChangeVMUserPasswordResponse, error)
	AttachCloudInit(context.Context, *AttachCloudInitRequest) (*AttachCloudInitResponse, error)
	AttachNetworkInterface(context.Context, *AttachNetworkInterfaceRequest) (*AttachNetworkInterfaceResponse, error)
	DetachNetworkInterface(context.Context, *DetachNetworkInterfaceRequest) (*DetachNetworkInterfaceResponse, error)
	Stream(grpc.BidiStreamingServer[v1.StreamRequest, v1.StreamResponse]) error
	GetHardwareHealth(context.Context, *GetHardwareHealthRequest) (*GetHardwareHealthResponse, error)
	GetSensorData(context.Context, *GetSensorDataRequest) (*GetSensorDataResponse, error)
	DefineVM(context.Context, *DefineVMRequest) (*DefineVMResponse, error)
	GetVMDefinition(context.Context, *GetVMDefinitionRequest) (*GetVMDefinitionResponse, error)
	ControlVM(context.Context, *ControlVMRequest) (*ControlVMResponse, error)
	GetVMStatus(context.Context, *GetVMStatusRequest) (*GetVMStatusResponse, error)
	GetVMGuestInfo(context.Context, *GetVMGuestInfoRequest) (*GetVMGuestInfoResponse, error)
	CreatePowerSchedule(context.Context, *CreatePowerScheduleRequest) (*CreatePowerScheduleResponse, error)
	ListPowerSchedules(context.Context, *ListPowerSchedulesRequest) (*ListPowerSchedulesResponse, error)
	UpdatePowerSchedule(context.Context, *UpdatePowerScheduleRequest) (*UpdatePowerScheduleResponse, error)
	DeletePowerSchedule(context.Context, *DeletePowerScheduleRequest) (*DeletePowerScheduleResponse, error)
	WakeOnLAN(context.Context, *WakeOnLANRequest) (*WakeOnLANResponse, error)
	// Host Management & DCUI
	GetHostInfo(context.Context, *GetHostInfoRequest) (*HostInfo, error)
	GetSystemResources(context.Context, *GetSystemResourcesRequest) (*SystemResources, error)
	GetServiceStatus(context.Context, *GetServiceStatusRequest) (*ServiceStatusList, error)
	RestartService(context.Context, *RestartServiceRequest) (*RestartServiceResponse, error)
	GetNetworkConfig(context.Context, *GetNetworkConfigRequest) (*NetworkConfig, error)
	ConfigureNetworkInterface(context.Context, *ConfigureNetworkInterfaceRequest) (*ConfigureNetworkInterfaceResponse, error)
	TestNetwork(context.Context, *TestNetworkRequest) (*NetworkTestResult, error)
	GetStorageConfig(context.Context, *GetStorageConfigRequest) (*StorageConfig, error)
	MountNFS(context.Context, *MountNFSRequest) (*MountNFSResponse, error)
	UnmountNFS(context.Context, *UnmountNFSRequest) (*UnmountNFSResponse, error)
	GetMaintenanceMode(context.Context, *GetMaintenanceModeRequest) (*MaintenanceModeStatus, error)
	GetFirewallRules(context.Context, *GetFirewallRulesRequest) (*FirewallRuleList, error)
	AddFirewallRule(context.Context, *AddFirewallRuleRequest) (*AddFirewallRuleResponse, error)
	RemoveFirewallRule(context.Context, *RemoveFirewallRuleRequest) (*RemoveFirewallRuleResponse, error)
	GetDNSConfig(context.Context, *GetDNSConfigRequest) (*DNSConfig, error)
	SetDNSConfig(context.Context, *SetDNSConfigRequest) (*SetDNSConfigResponse, error)
	GetNTPConfig(context.Context, *GetNTPConfigRequest) (*NTPConfig, error)
	SetNTPConfig(context.Context, *SetNTPConfigRequest) (*SetNTPConfigResponse, error)
	GetCloudStatus(context.Context, *GetCloudStatusRequest) (*CloudStatus, error)
	AdoptToCloud(context.Context, *AdoptToCloudRequest) (*AdoptToCloudResponse, error)
	DisconnectFromCloud(context.Context, *DisconnectFromCloudRequest) (*DisconnectFromCloudResponse, error)
	UpdateConfig(context.Context, *UpdateConfigRequest) (*UpdateConfigResponse, error)
	// Snapshot Management
	ListSnapshots(context.Context, *ListSnapshotsRequest) (*ListSnapshotsResponse, error)
	ConsolidateSnapshot(context.Context, *ConsolidateSnapshotRequest) (*ConsolidateSnapshotResponse, error)
	CloneSnapshot(context.Context, *CloneSnapshotRequest) (*CloneSnapshotResponse, error)
	// Volume Management
	CreateVolume(context.Context, *CreateVolumeRequest) (*CreateVolumeResponse, error)
	DeleteVolume(context.Context, *DeleteVolumeRequest) (*DeleteVolumeResponse, error)
	ResizeVolume(context.Context, *ResizeVolumeRequest) (*ResizeVolumeResponse, error)
	ListVolumes(context.Context, *ListVolumesRequest) (*ListVolumesResponse, error)
	GetVolume(context.Context, *GetVolumeRequest) (*GetVolumeResponse, error)
	CloneVolume(context.Context, *CloneVolumeRequest) (*CloneVolumeResponse, error)
	BackupSystemVolume(context.Context, *BackupSystemVolumeRequest) (*BackupSystemVolumeResponse, error)
	RestoreSystemVolume(context.Context, *RestoreSystemVolumeRequest) (*RestoreSystemVolumeResponse, error)
	// ConfigureManagementNetwork changes the addressing of the NIC that holds
	// the management role (node.yaml) with an automatic revert: the new
	// configuration is applied, and unless ConfirmNetworkChange arrives (from a
	// client that reached the node on the new address) before revert_after, the
	// previous addresses and default route are restored. A change that cuts the
	// operator off therefore undoes itself.
	ConfigureManagementNetwork(context.Context, *ConfigureManagementNetworkRequest) (*ConfigureManagementNetworkResponse, error)
	// CreateMigrationPairing mints a one-time token on a destination node that
	// lets one source agent migrate one VM here. Refused on managed nodes, which
	// migrate only through the director.
	CreateMigrationPairing(context.Context, *CreateMigrationPairingRequest) (*CreateMigrationPairingResponse, error)
	ConfirmNetworkChange(context.Context, *ConfirmNetworkChangeRequest) (*ConfirmNetworkChangeResponse, error)
	mustEmbedUnimplementedAgentServiceServer()
}

// UnimplementedAgentServiceServer must be embedded to have
// forward compatible implementations.
//
// NOTE: this should be embedded by value instead of pointer to avoid a nil
// pointer dereference when methods are called.
type UnimplementedAgentServiceServer struct{}

